  for (const [url, canonicalPath] of cases) {
    assert.deepEqual(sanitizeSpeedInsightsEvent({ type: "vital", url, route: "/unsafe/[value]" }), {
      type: "vital",
      url: `https://chaarlie.de${canonicalPath}`,
      route: canonicalPath,
    })
  }
})

