    loadClient,
    onReady: (nextClient) => tracker.setClient(nextClient),
  })

  assert.equal(await runtime.start(), true)
  assert.deepEqual(settings, [{ cdnURL: "https://cdp-eu.customer.io", writeKey: "write-key" }])
  assert.deepEqual(calls, [
